# Initially generated by GitHub Copilot.
"""Cross-repo hygiene/standards checks.

Scaffold for a growing set of independent, best-effort checks -- a repo
missing a convention (e.g. no requirements.txt) is reported, not treated as
a hard error. Checks fall into two groups:

Repo-level (single file each):
  - maintenance_script: does the repo have a repo-maintenance entrypoint?
  - gitattributes_lf: does .gitattributes force LF (`eol=lf`)?
  - path_utility: does the repo have a __file__-relative repo-root path
    utility (see MAM-basics issue #75), instead of scattered
    Path(__file__).resolve().parents[N] chains or cwd-relative literals?
  - black_pin: is `black` version-pinned in requirements.txt (unpinned
    installs can silently drift `--run-black` formatting across repos)?

File-scan (over tracked *.py files):
  - hex_escape_style: `\\uXXXX`/`\\UXXXXXXXX` escapes in a *non-raw* string,
    which should generally be the self-documenting `\\N{UNICODE NAME}` form
    instead. Escapes inside raw strings (`r"..."`) are exempted: that's the
    accepted, necessary form for a regex character-class range such as
    `r"\\u0591-\\u05ae\\u05bd"`, since `\\N{...}` can't express a range --
    confirmed as the standing convention in sibling repos (e.g.
    holman-ketiv-qere's hebrew_accents.py). Flagging those would be noise,
    not signal.
  - orphan_combining_mark: a bare Unicode combining mark (category Mn/Mc)
    immediately following a quote character in source -- it has no base
    character to attach to, so it renders as a floating/invisible diacritic
    on the opening quote itself. See user-level CLAUDE.md's "no orphan
    combining marks" rule.

Both file-scan checks are heuristic text scans (matching this repo's existing
style, e.g. tests/test_h_dot_below_nfc.py, and book-of-job's
check_escape_sequences.py), not a full tokenizer/AST parse.
"""
from __future__ import annotations

import re
import unicodedata
from pathlib import Path

from repo_util.common import run_cmd, write_json, write_text
from repo_util.repo_selection import RepoInfo

_MAINTENANCE_SCRIPT_CANDIDATES = (
    "py/main_repo_maintenance.py",
    "tools/repo_maintenance.py",
    "main_repo_maintenance.py",
)

_PATH_UTILITY_CANDIDATES = (
    "py/mb_cmn/paths.py",
    "py/repo_paths.py",
    "repo_paths.py",
)

_GITATTRIBUTES_LF_PATTERN = re.compile(r"^\*\s+text=auto\s+eol=lf\s*$", re.MULTILINE)

_BLACK_PIN_PATTERN = re.compile(r"^black\s*(==|~=|>=)", re.IGNORECASE)

_HEX_ESCAPE_PATTERN = re.compile(r"\\[uU][0-9A-Fa-f]{4,8}")

_RAW_STRING_SPAN_PATTERN = re.compile(
    r"""(?:[rR][bBfF]?|[bBfF][rR])(?P<q>'''|\"\"\"|'|\")(?:(?!(?P=q)).)*?(?P=q)""",
    re.DOTALL,
)

_RANGE_PATTERN = re.compile(r"\\[uU][0-9A-Fa-f]{4,8}-\\[uU][0-9A-Fa-f]{4,8}")

_QUOTE_CHARS = ("'", '"')

# This checker's own source mentions the escape/quote patterns it looks for
# only inside regex literals, which do not themselves match (see docstring),
# but it is excluded anyway to match this repo's existing self-exclusion
# convention (e.g. tests/test_h_dot_below_nfc.py's _EXCLUDE_189_FILES).
_SELF_RELATIVE_PATH = "py/repo_util/check_repo_standards.py"


def _has_any(repo_dir: Path, candidates: tuple[str, ...]) -> str | None:
    for rel in candidates:
        if (repo_dir / rel).is_file():
            return rel
    return None


def _check_maintenance_script(repo_dir: Path) -> dict:
    found = _has_any(repo_dir, _MAINTENANCE_SCRIPT_CANDIDATES)
    return {"present": found is not None, "path": found}


def _check_gitattributes_lf(repo_dir: Path) -> dict:
    gitattributes = repo_dir / ".gitattributes"
    if not gitattributes.is_file():
        return {"present": False, "has_eol_lf_rule": False}
    text = gitattributes.read_text(encoding="utf-8")
    return {
        "present": True,
        "has_eol_lf_rule": _GITATTRIBUTES_LF_PATTERN.search(text) is not None,
    }


def _check_path_utility(repo_dir: Path) -> dict:
    found = _has_any(repo_dir, _PATH_UTILITY_CANDIDATES)
    return {"present": found is not None, "path": found}


def _check_black_pin(repo_dir: Path) -> dict:
    requirements = repo_dir / "requirements.txt"
    if not requirements.is_file():
        return {
            "requirements_txt_present": False,
            "has_black_line": False,
            "black_pinned": False,
        }
    lines = [
        line.strip()
        for line in requirements.read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]
    black_lines = [line for line in lines if line.casefold().startswith("black")]
    return {
        "requirements_txt_present": True,
        "has_black_line": bool(black_lines),
        "black_pinned": any(_BLACK_PIN_PATTERN.match(line) for line in black_lines),
    }


def _tracked_py_files(repo_dir: Path) -> list[str]:
    result = run_cmd(["git", "-C", str(repo_dir), "ls-files", "*.py"])
    if result.returncode != 0:
        raise RuntimeError(
            result.stderr.strip() or f"Failed to list tracked .py files in {repo_dir}"
        )
    return [line for line in result.stdout.splitlines() if line.strip()]


def _is_excluded_from_scan(rel_path: str, *, exclude_novc: bool, exclude_dot_venv: bool) -> bool:
    normalized = rel_path.replace("\\", "/")
    if normalized == _SELF_RELATIVE_PATH:
        return True
    if exclude_dot_venv and "/.venv/" in f"/{normalized}/":
        return True
    if exclude_novc and "/.novc/" in f"/{normalized}/":
        return True
    if "__pycache__" in normalized:
        return True
    return False


def _raw_string_spans(text: str) -> list[tuple[int, int]]:
    """Return (start, end) character-offset spans of raw(-ish) string
    literals (r"...", rb'...', rf"...", fr'...', etc.). \\N{...} is not
    processed inside a raw string at all (raw strings disable all backslash
    escapes), so \\uXXXX there is the only option, not a style choice.
    Adapted from book-of-job's check_escape_sequences.py::_raw_string_spans."""
    return [match.span() for match in _RAW_STRING_SPAN_PATTERN.finditer(text)]


def _range_spans(text: str) -> list[tuple[int, int]]:
    """Return spans of \\uXXXX-\\uYYYY character-class range pairs. \\N{...}
    can express a single named character, never a range, so both endpoints
    are exempt regardless of raw-string-ness -- see e.g. non-raw
    RECC_APCV = "\\u0591-\\u05c7" in mb_cmn/hebrew_points.py."""
    return [match.span() for match in _RANGE_PATTERN.finditer(text)]


def _in_any_span(index: int, spans: list[tuple[int, int]]) -> bool:
    return any(start <= index < end for start, end in spans)


def _has_unicode_name(hex_digits: str) -> bool:
    """True if chr(int(hex_digits, 16)) has an assigned Unicode name -- i.e.
    a \\N{...} substitute is even possible. False for private-use-area and
    noncharacter codepoints (e.g. sentinels like "\\ufdd0", "\\ue010"), which
    have no assigned name and so must stay as \\uXXXX."""
    try:
        unicodedata.name(chr(int(hex_digits, 16)))
        return True
    except ValueError:
        return False


def _find_hex_escapes(text: str) -> list[int]:
    """Return 1-indexed line numbers with a \\uXXXX/\\UXXXXXXXX escape that
    could have been the self-documenting \\N{UNICODE NAME} form instead.
    Exempts raw strings, \\uXXXX-\\uYYYY range pairs, and codepoints with no
    assigned Unicode name -- none of those are a \\uXXXX-vs-\\N{} style
    choice, they're the only option available."""
    raw_spans = _raw_string_spans(text)
    range_spans = _range_spans(text)
    line_numbers = []
    for match in _HEX_ESCAPE_PATTERN.finditer(text):
        if _in_any_span(match.start(), raw_spans):
            continue
        if _in_any_span(match.start(), range_spans):
            continue
        if not _has_unicode_name(match.group(0)[2:]):
            continue
        line_no = text.count("\n", 0, match.start()) + 1
        if line_no not in line_numbers:
            line_numbers.append(line_no)
    return line_numbers


def _find_orphan_combining_marks(text: str) -> list[int]:
    """Return 1-indexed line numbers where a quote char is immediately
    followed by a bare combining mark (category Mn/Mc) -- the mark has no
    preceding base character in the literal, so it visually lands on the
    quote itself."""
    line_numbers = []
    for line_no, line in enumerate(text.split("\n"), start=1):
        for i, ch in enumerate(line[:-1]):
            if ch not in _QUOTE_CHARS:
                continue
            nxt = line[i + 1]
            if unicodedata.category(nxt) in ("Mn", "Mc"):
                line_numbers.append(line_no)
                break
    return line_numbers


def _scan_py_files(
    repo_dir: Path, *, exclude_novc: bool, exclude_dot_venv: bool
) -> dict:
    hex_escape_findings = []
    orphan_mark_findings = []
    scanned = 0
    for rel_path in _tracked_py_files(repo_dir):
        if _is_excluded_from_scan(
            rel_path, exclude_novc=exclude_novc, exclude_dot_venv=exclude_dot_venv
        ):
            continue
        full_path = repo_dir / rel_path
        if not full_path.is_file():
            continue
        scanned += 1
        text = full_path.read_text(encoding="utf-8")
        hex_escape_findings.extend(
            f"{rel_path}:{line_no}" for line_no in _find_hex_escapes(text)
        )
        orphan_mark_findings.extend(
            f"{rel_path}:{line_no}" for line_no in _find_orphan_combining_marks(text)
        )
    return {
        "py_file_count_scanned": scanned,
        "hex_escape_findings": hex_escape_findings,
        "orphan_combining_mark_findings": orphan_mark_findings,
    }


def _render_txt_report(results: list[dict]) -> str:
    lines: list[str] = []
    for repo in results:
        lines.append(f"=== {repo['repo']} ===")
        lines.append(f"maintenance_script: {repo['maintenance_script']}")
        lines.append(f"gitattributes_lf: {repo['gitattributes_lf']}")
        lines.append(f"path_utility: {repo['path_utility']}")
        lines.append(f"black_pin: {repo['black_pin']}")
        lines.append(f"py_file_count_scanned: {repo['py_file_count_scanned']}")
        if repo["hex_escape_findings"]:
            lines.append("hex_escape_findings:")
            for finding in repo["hex_escape_findings"]:
                lines.append(f"  - {finding}")
        if repo["orphan_combining_mark_findings"]:
            lines.append("orphan_combining_mark_findings:")
            for finding in repo["orphan_combining_mark_findings"]:
                lines.append(f"  - {finding}")
        lines.append("")
    return "\n".join(lines) + "\n"


def run_check_repo_standards_across_repos(
    repo_infos: list[RepoInfo],
    *,
    exclude_novc: bool,
    exclude_dot_venv: bool,
    report_json: Path | None,
    report_txt: Path | None,
) -> list[dict]:
    results: list[dict] = []

    for repo_info in repo_infos:
        repo_dir = repo_info.path
        scan = _scan_py_files(
            repo_dir, exclude_novc=exclude_novc, exclude_dot_venv=exclude_dot_venv
        )
        results.append(
            {
                "repo": repo_info.name,
                "maintenance_script": _check_maintenance_script(repo_dir),
                "gitattributes_lf": _check_gitattributes_lf(repo_dir),
                "path_utility": _check_path_utility(repo_dir),
                "black_pin": _check_black_pin(repo_dir),
                **scan,
            }
        )

    if report_json is not None:
        write_json(report_json, results)
    if report_txt is not None:
        write_text(report_txt, _render_txt_report(results))

    print(f"REPO_COUNT={len(results)}")
    for repo in results:
        print(
            "REPO={0}; MAINTENANCE_SCRIPT={1}; GITATTRIBUTES_LF={2}; "
            "PATH_UTILITY={3}; BLACK_PINNED={4}; HEX_ESCAPES={5}; "
            "ORPHAN_MARKS={6}".format(
                repo["repo"],
                repo["maintenance_script"]["present"],
                repo["gitattributes_lf"]["has_eol_lf_rule"],
                repo["path_utility"]["present"],
                repo["black_pin"]["black_pinned"],
                len(repo["hex_escape_findings"]),
                len(repo["orphan_combining_mark_findings"]),
            )
        )

    return results
